<original_code>
#include <bits/stdc++.h>
#define endl '\n'
using namespace std;

struct Solver {
    int n, t;
    string grid[10];
    int sci[10][10] = {};
    int resc[10][10] = {};
    int inf_time[10][10] = {};
    int reach_time[10][10][10][10];
    int di[4] = {-1,1,0,0};
    int dj[4] = {0,0,-1,1};

    static const int FLOW_N = 2 * 10 * 10 + 2;
    static const int INF = 1000000000;
    vector<int> adj[FLOW_N+1];
    int cap[FLOW_N+1][FLOW_N+1], flow[FLOW_N+1][FLOW_N+1];
    int ptr[FLOW_N+1], level[FLOW_N+1], parent[FLOW_N+1];

    void add_edge(int u, int v, int c) {
        adj[u].push_back(v);
        adj[v].push_back(u);
        cap[u][v] += c;
    }

    bool bfs_level(int s, int t) {
        memset(level, -1, sizeof(level));
        level[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                if (cap[u][v] - flow[u][v] > 0 && level[v] == -1) {
                    level[v] = level[u] + 1;
                    q.push(v);
                }
            }
        }
        return level[t] != -1;
    }

    bool dfs_find(int u, int t) {
        if (u == t) return true;
        for (int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
            int v = adj[u][i];
            if (level[v] == level[u] + 1 && cap[u][v] - flow[u][v] > 0 && dfs_find(v, t)) {
                parent[v] = u;
                return true;
            }
        }
        return false;
    }

    int maxFlow(int s, int t) {
        int ans = 0;
        while (bfs_level(s, t)) {
            memset(ptr, 0, sizeof(ptr));
            while (true) {
                memset(parent, -1, sizeof(parent));
                parent[s] = 0;
                if (!dfs_find(s, t)) break;
                int add = INF;
                for (int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                    add = min(add, cap[u][v] - flow[u][v]);
                }
                for (int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                    flow[u][v] += add;
                    flow[v][u] -= add;
                }
                ans += add;
            }
        }
        return ans;
    }

    int node(int i, int j, bool right) {
        return i * n + j + (right ? n * n : 0);
    }

    void solve() {
        cin >> n >> t;
        string line;
        pair<int,int> bomb;
        for (int i = 0; i < n; ++i) {
            cin >> line;
            for (int j = 0; j < n; ++j) {
                if (line[j] == 'Y') grid[i][j] = 'Y';
                else if (line[j] == 'Z') {
                    grid[i][j] = 'Z';
                    bomb = {i, j};
                } else {
                    grid[i][j] = '.';
                    sci[i][j] += line[j] - '0';
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            cin >> line;
            for (int j = 0; j < n; ++j) {
                if (line[j] != 'Y' && line[j] != 'Z') resc[i][j] += line[j] - '0';
            }
        }

        memset(inf_time, -1, sizeof(inf_time));
        inf_time[bomb.first][bomb.second] = 0;
        queue<pair<int,int>> q;
        q.push(bomb);
        while (!q.empty()) {
            int i = q.front().first, j = q.front().second;
            q.pop();
            for (int d = 0; d < 4; ++d) {
                int ni = i + di[d], nj = j + dj[d];
                if (0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni][nj] == '.' && inf_time[ni][nj] == -1) {
                    inf_time[ni][nj] = inf_time[i][j] + 1;
                    q.push({ni, nj});
                }
            }
        }

        memset(reach_time, -1, sizeof(reach_time));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] != '.') continue;
                reach_time[i][j][i][j] = 0;
                queue<pair<int,int>> q;
                q.push({i, j});
                while (!q.empty()) {
                    int ii = q.front().first, jj = q.front().second;
                    q.pop();
                    if (inf_time[ii][jj] == -1 || reach_time[i][j][ii][jj] < inf_time[ii][jj]) {
                        for (int d = 0; d < 4; ++d) {
                            int ni = ii + di[d], nj = jj + dj[d];
                            if (0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni][nj] == '.'
                                && (inf_time[ni][nj] == -1 || reach_time[i][j][ii][jj] + 1 <= inf_time[ni][nj])
                                && reach_time[i][j][ni][nj] == -1) {
                                reach_time[i][j][ni][nj] = reach_time[i][j][ii][jj] + 1;
                                q.push({ni, nj});
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i <= FLOW_N; ++i) adj[i].clear();
        memset(cap, 0, sizeof(cap));
        memset(flow, 0, sizeof(flow));

        int src = 2 * n * n;
        int sink = src + 1;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (sci[i][j]) add_edge(src, node(i, j, false), sci[i][j]);
                if (resc[i][j]) add_edge(node(i, j, true), sink, resc[i][j]);
                for (int ii = 0; ii < n; ++ii) {
                    for (int jj = 0; jj < n; ++jj) {
                        if (0 <= reach_time[i][j][ii][jj] && reach_time[i][j][ii][jj] <= t) {
                            add_edge(node(i, j, false), node(ii, jj, true), INF);
                        }
                    }
                }
            }
        }

        cout << maxFlow(src, sink) << endl;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    Solver solver;
    solver.solve();
    return 0;
}
